#!/usr/bin/env bash
set -euo pipefail

if [[ $# -ne 2 ]]; then
  echo "usage: $0 <output.cc> <path-to-mlx/backend/metal/kernels/utils.h>" >&2
  exit 2
fi

output=$1
utils_header=$2
kernels_suffix="/mlx/backend/metal/kernels/utils.h"

if [[ "${utils_header}" != *"${kernels_suffix}" ]]; then
  echo "expected second argument to end with ${kernels_suffix}: ${utils_header}" >&2
  exit 2
fi

src_root=${utils_header%"${kernels_suffix}"}
kernels_root="${src_root}/mlx/backend/metal/kernels"

functions=(
  "utils:utils"
  "binary_ops:binary_ops"
  "unary_ops:unary_ops"
  "ternary_ops:ternary_ops"
  "reduce_utils:reduce_utils"
  "gather:indexing/gather"
  "scatter:indexing/scatter"
  "masked_scatter:indexing/masked_scatter"
  "arange:arange"
  "unary:unary"
  "binary:binary"
  "binary_two:binary_two"
  "copy:copy"
  "fft:fft"
  "gather_axis:indexing/gather_axis"
  "gather_front:indexing/gather_front"
  "hadamard:hadamard"
  "logsumexp:logsumexp"
  "quantized_utils:quantized_utils"
  "quantized:quantized"
  "fp_quantized:fp_quantized"
  "ternary:ternary"
  "scan:scan"
  "scatter_axis:indexing/scatter_axis"
  "softmax:softmax"
  "sort:sort"
  "reduce:reduce"
  "gemm:steel/gemm/gemm"
  "steel_gemm_fused:steel/gemm/kernels/steel_gemm_fused"
  "steel_gemm_masked:steel/gemm/kernels/steel_gemm_masked"
  "steel_gemm_splitk:steel/gemm/kernels/steel_gemm_splitk"
  "steel_gemm_gather:steel/gemm/kernels/steel_gemm_gather"
  "steel_gemm_segmented:steel/gemm/kernels/steel_gemm_segmented"
  "conv:steel/conv/conv"
  "steel_conv:steel/conv/kernels/steel_conv"
  "steel_conv_3d:steel/conv/kernels/steel_conv_3d"
  "steel_conv_general:steel/conv/kernels/steel_conv_general"
  "gemv_masked:gemv_masked"
  "steel_attention:steel/attn/kernels/steel_attention"
  "gemm_nax:steel/gemm/gemm_nax"
  "steel_gemm_fused_nax:steel/gemm/kernels/steel_gemm_fused_nax"
  "steel_gemm_gather_nax:steel/gemm/kernels/steel_gemm_gather_nax"
  "steel_gemm_splitk_nax:steel/gemm/kernels/steel_gemm_splitk_nax"
  "steel_gemm_segmented_nax:steel/gemm/kernels/steel_gemm_segmented_nax"
  "quantized_nax:quantized_nax"
  "fp_quantized_nax:fp_quantized_nax"
  "steel_attention_nax:steel/attn/kernels/steel_attention_nax"
)

emit_file() {
  local rel=$1
  local path="${kernels_root}/${rel}"

  if [[ "${seen_list}" == *$'\n'"${rel}"$'\n'* ]]; then
    return
  fi
  seen_list="${seen_list}${rel}"$'\n'

  if [[ ! -f "${path}" ]]; then
    echo "missing MLX Metal kernel header: ${rel}" >&2
    exit 1
  fi

  printf '\n///////////////////////////////////////////////////////////////////////////////\n'
  printf '// Contents from "mlx/backend/metal/kernels/%s"\n' "${rel}"
  printf '///////////////////////////////////////////////////////////////////////////////\n\n'
  printf '#line 1 "mlx/backend/metal/kernels/%s"\n' "${rel}"

  local line include_rel
  while IFS= read -r line || [[ -n "${line}" ]]; do
    if [[ "${line}" =~ ^[[:space:]]*#[[:space:]]*pragma[[:space:]]+once([[:space:]]*)?$ ]]; then
      continue
    fi
    if [[ "${line}" =~ ^[[:space:]]*#[[:space:]]*include[[:space:]]+\"mlx/backend/metal/kernels/([^\"]+)\" ]]; then
      include_rel=${BASH_REMATCH[1]}
      emit_file "${include_rel}"
      continue
    fi
    printf '%s\n' "${line}"
  done < "${path}"
}

mkdir -p "$(dirname "${output}")"

{
  cat <<'EOF'
// Copyright © 2025 Apple Inc.
// Copyright © 2026 PjRTx contributors.
//
// Generated by third_party/mlx/generate_metal_jit_includes.sh.
// This mirrors MLX's CMake-generated jit/*.cpp files without invoking xcrun.

namespace mlx::core::metal {

EOF

  for entry in "${functions[@]}"; do
    fn=${entry%%:*}
    root=${entry#*:}
    seen_list=$'\n'

    printf 'const char* %s() {\n' "${fn}"
    printf '  return R"PjRTxMlxJit(\n'
    printf '#define MLX_METAL_JIT 1\n'
    emit_file "${root}.h"
    printf '\n///////////////////////////////////////////////////////////////////////////////\n'
    printf ')PjRTxMlxJit";\n'
    printf '}\n\n'
  done

  cat <<'EOF'
}  // namespace mlx::core::metal
EOF
} > "${output}"
